910	    if (TT.isNVPTX()) {
911	      if (TT.getVendor() == llvm::Triple::UnknownVendor)
912	        TT.setVendor(llvm::Triple::NVIDIA);
913	      if (TT.getOS() == llvm::Triple::UnknownOS)
