915	      return;
916	    }
917	
918	    if (TT.isAMDGPU()) {
919	      if (TT.getVendor() == llvm::Triple::UnknownVendor)
920	        TT.setVendor(llvm::Triple::AMD);
921	      if (TT.getOS() == llvm::Triple::UnknownOS)
922	        TT.setOS(llvm::Triple::AMDHSA);
923	      return;
924	    }
925	  }
