6144	InputInfoList Driver::BuildJobsForActionNoCache(
6145	    Compilation &C, const Action *A, const ToolChain *TC, BoundArch BA,
6146	    bool AtTopLevel, bool MultipleArchs, const char *LinkingOutput,
6147	    std::map<std::pair<const Action *, std::string>, InputInfoList>
6148	        &CachedResults,
6149	    Action::OffloadKind TargetDeviceOffloadKind) const {
6150	  llvm::PrettyStackTraceString CrashInfo("Building compilation jobs");
6151	
6152	  // Track the bound arch for commands constructed in this scope so
6153	  // generateCompilationDiagnostics can identify the crashing arch.
6154	  BoundArch SavedBoundArch = C.getCurrentBoundArch();
6155	  C.setCurrentBoundArch(BA);
6156	  auto RestoreBoundArch =
6157	      llvm::scope_exit([&] { C.setCurrentBoundArch(SavedBoundArch); });
6158	
6159	  InputInfoList OffloadDependencesInputInfo;
6160	  bool BuildingForOffloadDevice = TargetDeviceOffloadKind != Action::OFK_None;
6161	  if (const OffloadAction *OA = dyn_cast<OffloadAction>(A)) {
6162	    // The 'Darwin' toolchain is initialized only when its arguments are
6163	    // computed. Get the default arguments for OFK_None to ensure that
6164	    // initialization is performed before processing the offload action.
6165	    // FIXME: Remove when darwin's toolchain is initialized during construction.
6166	    C.getArgsForToolChain(TC, BA, Action::OFK_Host);
6167	
6168	    // The offload action is expected to be used in four different situations.
6169	    //
6170	    // a) Set a toolchain/architecture/kind for a host action:
6171	    //    Host Action 1 -> OffloadAction -> Host Action 2
6172	    //
6173	    // b) Set a toolchain/architecture/kind for a device action;
6174	    //    Device Action 1 -> OffloadAction -> Device Action 2
6175	    //
6176	    // c) Specify a device dependence to a host action;
6177	    //    Device Action 1  _
6178	    //                      \
6179	    //      Host Action 1  ---> OffloadAction -> Host Action 2
6180	    //
6181	    // d) Specify a host dependence to a device action.
6182	    //      Host Action 1  _
6183	    //                      \
6184	    //    Device Action 1  ---> OffloadAction -> Device Action 2
6185	    //
6186	    // For a) and b), we just return the job generated for the dependences. For
6187	    // c) and d) we override the current action with the host/device dependence
6188	    // if the current toolchain is host/device and set the offload dependences
6189	    // info with the jobs obtained from the device/host dependence(s).
6190	
6191	    // If there is a single device option or has no host action, just generate
6192	    // the job for it.
6193	    if (OA->hasSingleDeviceDependence() || !OA->hasHostDependence()) {
6194	      InputInfoList DevA;
6195	      OA->doOnEachDeviceDependence([&](Action *DepA, const ToolChain *DepTC,
6196	                                       BoundArch DepBoundArch) {
6197	        DevA.append(BuildJobsForAction(C, DepA, DepTC, DepBoundArch, AtTopLevel,
6198	                                       /*MultipleArchs=*/!DepBoundArch.empty(),
6199	                                       LinkingOutput, CachedResults,
6200	                                       DepA->getOffloadingDeviceKind()));
6201	      });
6202	      return DevA;
6203	    }
6204	
6205	    // If 'Action 2' is host, we generate jobs for the device dependences and
6206	    // override the current action with the host dependence. Otherwise, we
6207	    // generate the host dependences and override the action with the device
6208	    // dependence. The dependences can't therefore be a top-level action.
6209	    OA->doOnEachDependence(
6210	        /*IsHostDependence=*/BuildingForOffloadDevice,
6211	        [&](Action *DepA, const ToolChain *DepTC, BoundArch DepBoundArch) {
6212	          OffloadDependencesInputInfo.append(BuildJobsForAction(
6213	              C, DepA, DepTC, DepBoundArch, /*AtTopLevel=*/false,
6214	              /*MultipleArchs=*/!DepBoundArch.empty(), LinkingOutput,
6215	              CachedResults, DepA->getOffloadingDeviceKind()));
6216	        });
6217	
6218	    A = BuildingForOffloadDevice
6219	            ? OA->getSingleDeviceDependence(/*DoNotConsiderHostActions=*/true)
6220	            : OA->getHostDependence();
6221	
6222	    // We may have already built this action as a part of the offloading
6223	    // toolchain, return the cached input if so.
6224	    std::pair<const Action *, std::string> ActionTC = {
6225	        OA->getHostDependence(),
6226	        GetTriplePlusArchString(TC, BA, TargetDeviceOffloadKind)};
6227	    auto It = CachedResults.find(ActionTC);
6228	    if (It != CachedResults.end()) {
6229	      InputInfoList Inputs = It->second;
6230	      Inputs.append(OffloadDependencesInputInfo);
6231	      return Inputs;
6232	    }
6233	  }
6234	
6235	  if (const InputAction *IA = dyn_cast<InputAction>(A)) {
6236	    // FIXME: It would be nice to not claim this here; maybe the old scheme of
6237	    // just using Args was better?
6238	    const Arg &Input = IA->getInputArg();
6239	    Input.claim();
6240	    if (Input.getOption().matches(options::OPT_INPUT)) {
6241	      const char *Name = Input.getValue();
6242	      return {InputInfo(A, Name, /* _BaseInput = */ Name)};
6243	    }
6244	    return {InputInfo(A, &Input, /* _BaseInput = */ "")};
6245	  }
6246	
6247	  if (const BindArchAction *BAA = dyn_cast<BindArchAction>(A)) {
6248	    const ToolChain *TC;
6249	    BoundArch ArchName = BAA->getArch();
6250	
6251	    if (!ArchName.empty())
6252	      TC = &getToolChain(C.getArgs(),
6253	                         computeTargetTriple(*this, TargetTriple, C.getArgs(),
6254	                                             ArchName.ArchName));
6255	    else
6256	      TC = &C.getDefaultToolChain();
6257	
6258	    return BuildJobsForAction(C, *BAA->input_begin(), TC, ArchName, AtTopLevel,
6259	                              MultipleArchs, LinkingOutput, CachedResults,
6260	                              TargetDeviceOffloadKind);
6261	  }
6262	
6263	
6264	  ActionList Inputs = A->getInputs();
6265	
6266	  const JobAction *JA = cast<JobAction>(A);
6267	  ActionList CollapsedOffloadActions;
6268	
6269	  ToolSelector TS(JA, *TC, C, isSaveTempsEnabled(),
6270	                  embedBitcodeInObject() && !TC->isUsingLTO(C.getArgs()));
6271	  const Tool *T = TS.getTool(Inputs, CollapsedOffloadActions);
6272	
6273	  if (!T)
6274	    return {InputInfo()};
6275	
6276	  // If we've collapsed action list that contained OffloadAction we
6277	  // need to build jobs for host/device-side inputs it may have held.
6278	  for (const auto *OA : CollapsedOffloadActions)
6279	    cast<OffloadAction>(OA)->doOnEachDependence(
6280	        /*IsHostDependence=*/BuildingForOffloadDevice,
6281	        [&](Action *DepA, const ToolChain *DepTC, BoundArch DepBoundArch) {
6282	          OffloadDependencesInputInfo.append(BuildJobsForAction(
6283	              C, DepA, DepTC, DepBoundArch, /*AtTopLevel=*/false,
6284	              /*MultipleArchs=*/!DepBoundArch.empty(), LinkingOutput,
6285	              CachedResults, DepA->getOffloadingDeviceKind()));
6286	        });
6287	
6288	  // Only use pipes when there is exactly one input.
6289	  InputInfoList InputInfos;
6290	  for (const Action *Input : Inputs) {
6291	    // Treat dsymutil and verify sub-jobs as being at the top-level too, they
6292	    // shouldn't get temporary output names.
6293	    // FIXME: Clean this up.
6294	    bool SubJobAtTopLevel =
6295	        AtTopLevel && (isa<DsymutilJobAction>(A) || isa<VerifyJobAction>(A));
6296	    InputInfos.append(BuildJobsForAction(
6297	        C, Input, TC, BA, SubJobAtTopLevel, MultipleArchs, LinkingOutput,
6298	        CachedResults, A->getOffloadingDeviceKind()));
6299	  }
6300	
6301	  // Always use the first file input as the base input.
6302	  const char *BaseInput = InputInfos[0].getBaseInput();
6303	  for (auto &Info : InputInfos) {
6304	    if (Info.isFilename()) {
6305	      BaseInput = Info.getBaseInput();
6306	      break;
6307	    }
6308	  }
6309	
6310	  // ... except dsymutil actions, which use their actual input as the base
6311	  // input.
6312	  if (JA->getType() == types::TY_dSYM)
6313	    BaseInput = InputInfos[0].getFilename();
6314	
6315	  // Append outputs of offload device jobs to the input list
6316	  if (!OffloadDependencesInputInfo.empty())
6317	    InputInfos.append(OffloadDependencesInputInfo.begin(),
6318	                      OffloadDependencesInputInfo.end());
6319	
6320	  // Set the effective triple of the toolchain for the duration of this job.
6321	  llvm::Triple EffectiveTriple;
6322	  const ToolChain &ToolTC = T->getToolChain();
6323	  const ArgList &Args =
6324	      C.getArgsForToolChain(TC, BA, A->getOffloadingDeviceKind());
6325	  if (InputInfos.size() != 1) {
6326	    EffectiveTriple =
6327	        llvm::Triple(ToolTC.ComputeEffectiveClangTriple(Args, BA));
6328	  } else {
6329	    // Pass along the input type if it can be unambiguously determined.
6330	    EffectiveTriple = llvm::Triple(
6331	        ToolTC.ComputeEffectiveClangTriple(Args, BA, InputInfos[0].getType()));
6332	  }
6333	  RegisterEffectiveTriple TripleRAII(ToolTC, EffectiveTriple);
6334	
6335	  // Determine the place to write output to, if any.
6336	  InputInfo Result;
6337	  InputInfoList UnbundlingResults;
6338	  if (auto *UA = dyn_cast<OffloadUnbundlingJobAction>(JA)) {
6339	    // If we have an unbundling job, we need to create results for all the
6340	    // outputs. We also update the results cache so that other actions using
6341	    // this unbundling action can get the right results.
6342	    for (auto &UI : UA->getDependentActionsInfo()) {
6343	      assert(UI.DependentOffloadKind != Action::OFK_None &&
6344	             "Unbundling with no offloading??");
6345	
6346	      // Unbundling actions are never at the top level. When we generate the
6347	      // offloading prefix, we also do that for the host file because the
6348	      // unbundling action does not change the type of the output which can
6349	      // cause a overwrite.
6350	      std::string OffloadingPrefix = Action::GetOffloadingFileNamePrefix(
6351	          UI.DependentOffloadKind, UI.DependentToolChain->getTripleString(),
6352	          /*CreatePrefixForHost=*/true);
6353	      auto CurI = InputInfo(
6354	          UA,
6355	          GetNamedOutputPath(C, *UA, BaseInput, UI.DependentBoundArch,
6356	                             /*AtTopLevel=*/false,
6357	                             MultipleArchs ||
6358	                                 UI.DependentOffloadKind == Action::OFK_HIP,
6359	                             OffloadingPrefix),
6360	          BaseInput);
6361	      // Save the unbundling result.
6362	      UnbundlingResults.push_back(CurI);
6363	
6364	      // Get the unique string identifier for this dependence and cache the
6365	      // result.
6366	      BoundArch Arch;
6367	      if (TargetDeviceOffloadKind == Action::OFK_HIP) {
6368	        if (UI.DependentOffloadKind == Action::OFK_Host)
6369	          Arch = BoundArch();
6370	        else
6371	          Arch = BoundArch(UI.DependentBoundArch);
6372	      } else
6373	        Arch = BA;
6374	
6375	      CachedResults[{A, GetTriplePlusArchString(UI.DependentToolChain, Arch,
6376	                                                UI.DependentOffloadKind)}] = {
6377	          CurI};
6378	    }
6379	
6380	    // Now that we have all the results generated, select the one that should be
6381	    // returned for the current depending action.
6382	    std::pair<const Action *, std::string> ActionTC = {
6383	        A, GetTriplePlusArchString(TC, BA, TargetDeviceOffloadKind)};

